tools.args:
{"command":"$paths = @(
  'C:\Program Files\Ghidra',
  'C:\ghidra',
  "$env:USERPROFILE\ghidra",
  'C:\Program Files\Hopper Disassembler',
  'C:\Program Files\IDA Professional',
  'C:\Program Files\IDA Free',
  'C:\Program Files\IDA'
)
foreach ($p in $paths) { if (Test-Path $p) { "FOUND: $p" } }
"--- PATH tools ---"
foreach ($t in @('ghidraRun','analyzeHeadless','ida','ida64','hopper','node','npx')) {
  $c = Get-Command $t -ErrorAction SilentlyContinue
  if ($c) { "$t -> $($c.Source)" } else { "$t -> NOT FOUND" }
}
"--- node/npm ---"
try { node -v } catch { "node missing" }
try { npm -v } catch { "npm missing" }","description":"Проверка наличия декомпиляторов и Node"}
